mapper.select:
SELECT t1.id, t1.order_id, so.order_no, t1.curtain_id, c.`name` AS curtain_name, soc.room, t1.structure_id, t31.`name` AS structure_name, t1.material_id, t41.`name` AS element_name, t1.node_id, t1.node_name, pn.`group` AS node_group, t1.status, t1.master_id, tm.`name` AS master_name, t1.assistant_id, ta.`name` AS assistant_name, t1.note, t1.image_urls, t1.create_time, t1.update_time FROM zc_order_process_record t1 LEFT JOIN zc_sales_order so ON t1.order_id = so.id AND so.deleted = 0 LEFT JOIN zc_sales_order_curtain soc ON t1.curtain_id = soc.id AND soc.deleted = 0 LEFT JOIN zc_curtain c ON soc.curtain_id = c.id AND c.deleted = 0 LEFT JOIN zc_sales_order_structure t3 ON t1.structure_id = t3.id LEFT JOIN zc_curtain_structure t31 ON t3.structure_id = t31.id LEFT JOIN zc_sales_order_material t4 ON t1.material_id = t4.id LEFT JOIN zc_curtain_structure_element t41 ON t4.element_id = t41.id INNER JOIN zc_process_node pn ON t1.node_id = pn.id AND pn.deleted = 0
AND pn.`group` IN
#{nodeGroup}
LEFT JOIN zc_workshop_user tm ON t1.master_id = tm.id AND tm.deleted = 0 LEFT JOIN zc_workshop_user ta ON t1.assistant_id = ta.id AND ta.deleted = 0 WHERE t1.deleted = 0
AND t1.order_id = #{orderId}
AND t1.master_id = #{masterId}
AND t1.curtain_id = #{curtainId}
AND t1.structure_id = #{structureId}
AND t1.material_id = #{materialId}
AND t1.node_id = #{nodeId}
ORDER BY t1.create_time DESC

SELECT COUNT(*) AS processCount, SUM(t4.quantity) AS totalQuantity FROM zc_order_process_record t1 LEFT JOIN zc_process_node_element t2 ON t1.node_id = t2.process_node_id LEFT JOIN zc_sales_order_material t4 ON t1.order_id = t4.order_id AND t1.structure_id = t4.order_structure_id AND t2.element_id = t4.element_id WHERE t1.deleted = 0 AND t1.status = 1 AND t1.master_id = #{masterId} AND t1.node_id = #{nodeId}
AND t1.create_time >= #{beginCreateTime}
AND t1.create_time <= #{endCreateTime}
